    """Truncated wave band rows are completed rightward: each row of an incomplete band gets `fill` where its best-matching (drift-aligned) row of the complete reference band has a marker, from one past the incomplete band's deepest tip to the right edge."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rest = Counter(v for row in grid for v in row if v != bg)
    marker = rest.most_common(1)[0][0]
    bands = []
    cur = None
    for i in range(h):
